import{_ as e,o as d,c as l,a3 as a}from"./chunks/framework.BbiCTsjF.js";const f=JSON.parse('{"title":"CLI 命令参考","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1786589620000}'),o={name:"reference/cli.md"};function s(i,t,c,n,r,g){return d(),l("div",null,[...t[0]||(t[0]=[a(`<h1 id="cli-命令参考" tabindex="-1">CLI 命令参考 <a class="header-anchor" href="#cli-命令参考" aria-label="Permalink to &quot;CLI 命令参考&quot;">​</a></h1><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forgeax -p &quot;&lt;prompt&gt;&quot;     一次性 print 模式</span></span>
<span class="line"><span>forgeax                   REPL / TUI</span></span>
<span class="line"><span>forgeax --demo -p &quot;hi&quot;    演示（无需 API key）</span></span>
<span class="line"><span>forgeax mcp-serve         反向 MCP server（stdio）</span></span>
<span class="line"><span>forgeax --serve --sock &lt;path&gt;   AgentKernel sidecar（进阶）</span></span></code></pre></div><p>命令别名：全局 bin 同时提供 <code>forgeax</code> 与 <code>forgeax-cli</code>（同一入口）。</p><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-p</code>, <code>--print &lt;prompt&gt;</code></td><td style="text-align:left;">跑一轮后退出</td></tr><tr><td style="text-align:left;"><code>--output-format &lt;fmt&gt;</code></td><td style="text-align:left;"><code>text</code>（默认）| <code>json</code> | <code>stream-json</code></td></tr><tr><td style="text-align:left;"><code>--model &lt;id&gt;</code></td><td style="text-align:left;">模型 id</td></tr><tr><td style="text-align:left;"><code>--demo</code></td><td style="text-align:left;">内置 echo provider，无网络</td></tr><tr><td style="text-align:left;"><code>--memory &lt;dir&gt;</code></td><td style="text-align:left;">auto-memory 目录（默认 <code>./.forgeax/memory</code>）</td></tr><tr><td style="text-align:left;"><code>--no-memory</code></td><td style="text-align:left;">关闭 auto-memory</td></tr><tr><td style="text-align:left;"><code>--skills &lt;dir,...&gt;</code></td><td style="text-align:left;">skill 根目录（否则自动发现）</td></tr><tr><td style="text-align:left;"><code>--commands &lt;dir,...&gt;</code></td><td style="text-align:left;">markdown command 目录</td></tr><tr><td style="text-align:left;"><code>--mcp &lt;config.json&gt;</code></td><td style="text-align:left;">MCP 配置；否则自动发现 mcp.json</td></tr><tr><td style="text-align:left;"><code>--mcp-token &lt;s=ENV|ENV&gt;</code></td><td style="text-align:left;">MCP bearer 的 env 名（按 server 或通配）</td></tr><tr><td style="text-align:left;"><code>--plugins &lt;dir,...&gt;</code></td><td style="text-align:left;">plugin 源目录</td></tr><tr><td style="text-align:left;"><code>--hooks &lt;config.json&gt;</code></td><td style="text-align:left;">PreToolUse 等 hooks</td></tr><tr><td style="text-align:left;"><code>--search-url &lt;url&gt;</code></td><td style="text-align:left;">web_search 后端</td></tr><tr><td style="text-align:left;"><code>--thinking [budget]</code></td><td style="text-align:left;">扩展思考（可选 token budget）</td></tr><tr><td style="text-align:left;"><code>--resume &lt;id&gt;</code></td><td style="text-align:left;">持久化并续接会话</td></tr><tr><td style="text-align:left;"><code>--session-id &lt;id&gt;</code></td><td style="text-align:left;">指定会话 id（新或已有；与 resume 对齐）</td></tr><tr><td style="text-align:left;"><code>-c</code>, <code>--continue</code></td><td style="text-align:left;">续本目录最近会话</td></tr><tr><td style="text-align:left;"><code>--sessions-dir &lt;dir&gt;</code></td><td style="text-align:left;">会话 WAL 根（默认 <code>./.forgeax/sessions</code>）</td></tr><tr><td style="text-align:left;"><code>--yes</code></td><td style="text-align:left;">⚠ 自动批准全部权限提示（root 拒绝）</td></tr><tr><td style="text-align:left;"><code>--permission-mode &lt;m&gt;</code></td><td style="text-align:left;"><code>default</code> | <code>acceptEdits</code> | <code>plan</code> | <code>bypassPermissions</code></td></tr><tr><td style="text-align:left;"><code>--no-tui</code></td><td style="text-align:left;">强制 readline</td></tr><tr><td style="text-align:left;"><code>--sandbox</code> / <code>--no-sandbox</code></td><td style="text-align:left;">OS Bash 沙箱</td></tr><tr><td style="text-align:left;"><code>--serve</code></td><td style="text-align:left;">sidecar 模式（需 <code>--sock</code> 或 <code>FORGEAX_CORE_SOCK</code>）</td></tr><tr><td style="text-align:left;"><code>--sock &lt;path&gt;</code></td><td style="text-align:left;">serve 用 unix socket</td></tr><tr><td style="text-align:left;"><code>-h</code>, <code>--help</code></td><td style="text-align:left;">帮助</td></tr><tr><td style="text-align:left;"><code>-v</code>, <code>--version</code></td><td style="text-align:left;">版本</td></tr></tbody></table><h2 id="子命令" tabindex="-1">子命令 <a class="header-anchor" href="#子命令" aria-label="Permalink to &quot;子命令&quot;">​</a></h2><h3 id="mcp-serve" tabindex="-1"><code>mcp-serve</code> <a class="header-anchor" href="#mcp-serve" aria-label="Permalink to &quot;\`mcp-serve\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forgeax</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-serve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--allow-writes] [与主 CLI 兼容的发现类 flag…]</span></span></code></pre></div><p>不接受 <code>--permission-mode</code>（该形态不创建交互 agent）。</p><h2 id="环境变量-摘要" tabindex="-1">环境变量（摘要） <a class="header-anchor" href="#环境变量-摘要" aria-label="Permalink to &quot;环境变量（摘要）&quot;">​</a></h2><p>见 <a href="./../configuration">设置与环境变量</a>。最常用：</p><ul><li><code>ANTHROPIC_API_KEY</code> / <code>ANTHROPIC_BASE_URL</code></li><li><code>OPENAI_API_KEY</code> / <code>OPENAI_BASE_URL</code> + <code>FORGEAX_PROVIDER_API=openai-compat</code></li><li><code>FORGEAX_MODEL</code></li><li><code>FORGEAX_CONFIG_DIR</code></li></ul><h2 id="退出与自动化" tabindex="-1">退出与自动化 <a class="header-anchor" href="#退出与自动化" aria-label="Permalink to &quot;退出与自动化&quot;">​</a></h2><ul><li>print 模式适合 CI：配合 <code>--output-format json</code> 解析</li><li>管道：stdin 非 TTY 时读入内容（有超时兜底，避免继承的空管道永久挂起）</li><li>权限：CI 中优先窄 <code>allow</code> 规则，慎用 <code>--yes</code></li></ul>`,15)])])}const x=e(o,[["render",s]]);export{f as __pageData,x as default};
